<?php
require_once __DIR__ . '/../helpers.php'; require_once __DIR__ . '/../config/database.php'; require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$a=$_POST['action']??'';if($a==='save'){$id=(int)($_POST['id']??0);$sku=strtoupper(trim((string)($_POST['sku']??'')));$name=trim((string)($_POST['name']??''));$cat=(int)($_POST['category_id']??0);$price=filter_var($_POST['price']??null,FILTER_VALIDATE_FLOAT);$suppliers=array_values(array_unique(array_filter(array_map('intval',$_POST['suppliers']??[]))));if(!preg_match('/^[A-Z0-9_-]{2,40}$/',$sku))throw new RuntimeException('SKU harus 2–40 karakter: huruf, angka, - atau _.');if($name===''||$cat<1||$price===false||$price<0)throw new RuntimeException('Nama, kategori, dan harga harus valid; harga tidak boleh negatif.');$pdo->beginTransaction();if($id){$s=$pdo->prepare('UPDATE products SET sku=?,name=?,category_id=?,price=? WHERE id=?');$s->execute([$sku,$name,$cat,$price,$id]);$pdo->prepare('DELETE FROM product_suppliers WHERE product_id=?')->execute([$id]);}else{$s=$pdo->prepare('INSERT INTO products(sku,name,category_id,price,quantity) VALUES(?,?,?,?,0)');$s->execute([$sku,$name,$cat,$price]);$id=(int)$pdo->lastInsertId();}foreach($suppliers as $sid){$s=$pdo->prepare('INSERT INTO product_suppliers(product_id,supplier_id) VALUES(?,?)');$s->execute([$id,$sid]);}$pdo->commit();flash('Produk disimpan.');}elseif($a==='delete'){require_admin();$id=(int)$_POST['id'];$s=$pdo->prepare('SELECT COUNT(*) FROM stock_transactions WHERE product_id=?');$s->execute([$id]);if((int)$s->fetchColumn()>0)throw new RuntimeException('Produk memiliki histori transaksi sehingga tidak boleh dihapus.');$s=$pdo->prepare('DELETE FROM products WHERE id=?');$s->execute([$id]);flash('Produk dihapus.');}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e instanceof PDOException?'Gagal menyimpan. Pastikan SKU unik dan kategori/supplier valid.':$e->getMessage(),'error');}redirect('products.php');}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM products WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();if($edit){$s=$pdo->prepare('SELECT supplier_id FROM product_suppliers WHERE product_id=?');$s->execute([$edit['id']]);$edit['suppliers']=array_map('intval',$s->fetchAll(PDO::FETCH_COLUMN));}}
$cats=$pdo->query('SELECT id,name FROM categories ORDER BY name')->fetchAll();$suppliers=$pdo->query('SELECT id,name FROM suppliers ORDER BY name')->fetchAll();
$q=trim((string)($_GET['q']??''));$catFilter=(int)($_GET['category_id']??0);$sorts=['name'=>'p.name','sku'=>'p.sku','price'=>'p.price','quantity'=>'p.quantity','category'=>'c.name'];$sort=$_GET['sort']??'name';$sortSql=$sorts[$sort]??$sorts['name'];$dir=strtolower((string)($_GET['dir']??'asc'))==='desc'?'DESC':'ASC';$page=max(1,(int)($_GET['page']??1));$limit=8;$where=[];$params=[];if($q!==''){$where[]='(p.name LIKE ? OR p.sku LIKE ?)';$params[]="%$q%";$params[]="%$q%";}if($catFilter){$where[]='p.category_id=?';$params[]=$catFilter;}$w=$where?' WHERE '.implode(' AND ',$where):'';$s=$pdo->prepare("SELECT COUNT(*) FROM products p JOIN categories c ON c.id=p.category_id".$w);$s->execute($params);$total=(int)$s->fetchColumn();$pages=max(1,(int)ceil($total/$limit));$page=min($page,$pages);$offset=($page-1)*$limit;$s=$pdo->prepare("SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id".$w." ORDER BY $sortSql $dir LIMIT $limit OFFSET $offset");$s->execute($params);$rows=$s->fetchAll();
layout_start('Produk');
echo '<div class="card"><h2>'.($edit?'Edit Produk':'Tambah Produk').'</h2><form method="post"><input type="hidden" name="csrf_token" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="'.(int)($edit['id']??0).'"><div class="grid"><div><label>SKU (unik)</label><input name="sku" maxlength="40" required value="'.e($edit['sku']??'').'"></div><div><label>Nama produk</label><input name="name" required value="'.e($edit['name']??'').'"></div><div><label>Kategori</label><select name="category_id" required><option value="">Pilih kategori</option>';foreach($cats as $c)echo '<option value="'.(int)$c['id'].'" '.((int)($edit['category_id']??0)===(int)$c['id']?'selected':'').'>'.e($c['name']).'</option>';echo '</select></div><div><label>Harga (Rp)</label><input type="number" min="0" step="0.01" name="price" required value="'.e($edit['price']??'0').'"></div></div><label>Supplier (boleh pilih lebih dari satu)</label><select name="suppliers[]" multiple size="3">';foreach($suppliers as $s)echo '<option value="'.(int)$s['id'].'" '.(in_array((int)$s['id'],$edit['suppliers']??[],true)?'selected':'').'>'.e($s['name']).'</option>';echo '</select><p class="muted">Stok awal diatur melalui menu Transaksi Stok agar riwayat tercatat.</p><button>Simpan Produk</button> <a class="btn secondary" href="products.php">Batal</a></form></div>';
echo '<div class="card"><form class="inline" method="get"><div><label>Cari nama/SKU</label><input name="q" value="'.e($q).'" placeholder="Contoh: mouse atau SKU001"></div><div><label>Filter kategori</label><select name="category_id"><option value="0">Semua kategori</option>';foreach($cats as $c)echo '<option value="'.(int)$c['id'].'" '.($catFilter===(int)$c['id']?'selected':'').'>'.e($c['name']).'</option>';echo '</select></div><div><label>Urutkan</label><select name="sort">';foreach(['name'=>'Nama','sku'=>'SKU','price'=>'Harga','quantity'=>'Stok','category'=>'Kategori'] as $k=>$v)echo '<option value="'.$k.'" '.($sort===$k?'selected':'').'>'.$v.'</option>';echo '</select></div><div><label>Arah</label><select name="dir"><option value="asc" '.($dir==='ASC'?'selected':'').'>Naik</option><option value="desc" '.($dir==='DESC'?'selected':'').'>Turun</option></select></div><div><button>Cari</button> <a class="btn secondary" href="products.php">Reset</a></div></form></div>';
echo '<div class="card table-wrap"><table><tr><th>SKU</th><th>Nama</th><th>Kategori</th><th>Harga</th><th>Stok</th><th>Aksi</th></tr>';foreach($rows as $r){echo '<tr><td>'.e($r['sku']).'</td><td>'.e($r['name']).'</td><td>'.e($r['category_name']).'</td><td>Rp '.number_format((float)$r['price'],0,',','.').'</td><td><span class="pill">'.(int)$r['quantity'].'</span></td><td><a class="btn secondary" href="?edit='.(int)$r['id'].'">Edit</a> ';if(current_user()['role']==='admin')echo '<form method="post" onsubmit="return confirm(\'Hapus produk ini?\')"><input type="hidden" name="csrf_token" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="'.(int)$r['id'].'"><button class="danger">Hapus</button></form>';echo '</td></tr>';}if(!$rows)echo '<tr><td colspan="6">Belum ada produk yang cocok.</td></tr>';echo '</table><p class="muted">Halaman '.$page.' dari '.$pages.' · '.$total.' produk</p><div class="inline">';for($i=1;$i<=$pages;$i++){if($i===$page)echo '<strong>'.$i.'</strong> ';else echo '<a class="btn secondary" href="?'.http_build_query(['q'=>$q,'category_id'=>$catFilter,'sort'=>$sort,'dir'=>strtolower($dir),'page'=>$i]).'">'.$i.'</a> ';}echo '</div></div>';layout_end();
